package com.tripmateai.security; import com.tripmateai.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor @Transactional(readOnly = true) public class CustomUserDetailsService implements UserDetailsService {private final UserRepository users; public UserDetails loadUserByUsername(String email){return new UserPrincipal(users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found")));}}
